import { forwardRef, useId, useRef } from 'react';
import { InputBase } from '../base/InputBase';
import { TextfieldPropsBase } from './Textfield.types';
import { useTextField } from './useTextfield';
import { useForkRef } from './useForkRef';
import { cx } from '../internal/cx';
import { useDefaults, slot, ClassNames } from '../internal/defaults';

const clamp = (n: number) => Math.max(0, Math.min(1, Number.isFinite(n) ? n : 0));

const defaultChargeLabel = (percent: number) =>
  percent >= 100 ? 'Fully charged' : percent === 0 ? 'No charge' : `${percent}% charged`;

/**
 * A text input with a label, helper text and error state built in. It also has
 * a party trick: a charge meter that fills up as the value gets more complete,
 * handy for password strength or profile progress.
 *
 * In Live Wire, a field can "charge up" as its value becomes valid.
 * Pass `charge` (0..1, or a function of the value) to show the meter.
 *
 * Style hooks: `.sp-textfield` with `[data-focused]`, `[data-invalid]`,
 * `[data-charged]`, `[data-disabled]`; parts `__label`, `__control`, `__input`,
 * `__adornment`, `__meter`, `__helper`. Built on InputBase (`.sp-input-base`).
 */
const Textfield = forwardRef<HTMLInputElement, TextfieldPropsBase>((props, ref) => {
  const {
    label,
    placeholder,
    disabled,
    error,
    prepend,
    append,
    value,
    defaultValue,
    onChange,
    onValueChange,
    onFocus,
    onBlur,
    inputSize = 'medium',
    helperText,
    containerStyle,
    isCurrency,
    cardDetection,
    formatPhoneNumber,
    variant,
    charge,
    chargeLabel = defaultChargeLabel,
    type,
    id,
    className,
    classNames,
    ...rest
  } = useDefaults('Textfield', props);

  const {
    value: fieldValue,
    onChange: handleChange,
    onFocus: handleFocus,
    onBlur: handleBlur,
    focused,
    disabled: isDisabled,
    error: hasError,
  } = useTextField({
    value: value ?? defaultValue,
    onChange:
      onChange || onValueChange
        ? (event) => {
            onChange?.(event);
            onValueChange?.(event.target.value, event);
          }
        : undefined,
    onFocus,
    onBlur,
    disabled,
    error,
    type,
  });
  const controlled = value !== undefined;
  // Controlled: the parent's value is the truth, so changes made outside the field
  // (a reset, data from the server) show up. Uncontrolled: the field keeps its own.
  const current = controlled ? String(value) : fieldValue;

  const level = charge === undefined ? undefined : clamp(typeof charge === 'function' ? charge(current) : charge);
  const percent = level === undefined ? 0 : Math.round(level * 100);
  const charged = level !== undefined && percent >= 100 && !hasError;

  const autoId = useId();
  const inputId = id ?? autoId;
  const helperId = `${inputId}-helper`;
  const meterId = `${inputId}-meter`;
  const describedBy = [helperText && helperId, level !== undefined && meterId].filter(Boolean).join(' ') || undefined;

  const inputRef = useRef<HTMLInputElement>(null);
  const handleRef = useForkRef(ref, inputRef);

  // Native input types only: the masking types are handled by useTextField.
  const masked = type === 'card' || type === 'currency' || type === 'phone';

  return (
    <div
      className={slot('sp-textfield', classNames, 'root', className)}
      data-tone={hasError ? 'error' : 'brand'}
      data-size={inputSize}
      data-focused={focused || undefined}
      data-invalid={hasError || undefined}
      data-charged={charged || undefined}
      data-disabled={isDisabled || undefined}
    >
      {label && (
        <label htmlFor={inputId} className={slot('sp-textfield__label', classNames, 'label')}>
          {label}
        </label>
      )}
      <InputBase
        ref={handleRef}
        id={inputId}
        size={inputSize}
        error={hasError}
        disabled={isDisabled}
        startAdornment={prepend}
        endAdornment={append}
        rootProps={{ style: containerStyle }}
        classNames={{
          root: slot('sp-textfield__control', classNames, 'control'),
          input: slot('sp-textfield__input', classNames, 'input'),
          adornment: slot('sp-textfield__adornment', classNames, 'adornment'),
        }}
        type={masked ? 'text' : type}
        inputMode={masked ? 'numeric' : undefined}
        placeholder={placeholder}
        {...(controlled ? { value: current } : { defaultValue })}
        aria-describedby={describedBy}
        onChange={handleChange}
        onFocus={handleFocus}
        onBlur={handleBlur}
        {...(rest as Omit<typeof rest, 'size'>)}
      />
      {level !== undefined && (
        <div id={meterId} className={slot('sp-textfield__meter', classNames, 'meter')}>
          <div
            role="meter"
            aria-label={typeof label === 'string' ? `${label} charge` : 'Charge'}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={percent}
            className="sp-textfield__meter-track"
          >
            <div className={cx('sp-textfield__meter-fill', percent >= 100 && 'sp-current')} style={{ width: `${percent}%` }} />
          </div>
          <span className="sp-textfield__meter-label" aria-live="polite">
            {chargeLabel(percent)}
          </span>
        </div>
      )}
      {helperText && (
        <p id={helperId} className={slot('sp-textfield__helper', classNames, 'helper')}>
          {helperText}
        </p>
      )}
    </div>
  );
});

Textfield.displayName = 'Textfield';

export default Textfield;

import { ChangeEvent, FocusEvent, InputHTMLAttributes } from 'react';

export interface UseTextFieldProps {
  value?: string;
  onChange?: (event: ChangeEvent<HTMLInputElement>) => void;
  onFocus?: (event: FocusEvent<HTMLInputElement>) => void;
  onBlur?: (event: FocusEvent<HTMLInputElement>) => void;
  disabled?: boolean;
  error?: boolean;
  type?:
  | "button"
  | "checkbox"
  | "color"
  | "date"
  | "datetime-local"
  | "email"
  | "file"
  | "hidden"
  | "image"
  | "month"
  | "password"
  | "radio"
  | "range"
  | "reset"
  | "search"
  | "submit"
  | "text"
  | "time"
  | "url"
  | "week"
  | 'card'
  | 'currency'
  | 'phone'
  | (string & {});
}

export interface UseTextFieldResult {
  /** The current text. */
  value: string;
  /** Pass to the input's onChange. */
  onChange: (event: ChangeEvent<HTMLInputElement>) => void;
  /** Pass to the input's onFocus. */
  onFocus: (event: FocusEvent<HTMLInputElement>) => void;
  /** Pass to the input's onBlur. */
  onBlur: (event: FocusEvent<HTMLInputElement>) => void;
  /** Whether the input has focus. */
  focused: boolean;
  /** Whether the field is disabled. */
  disabled: boolean;
  /** Whether the field is in its error state. */
  error: boolean;
}

export interface TextfieldPropsBase extends InputHTMLAttributes<HTMLInputElement> {
  /** Visible label, linked to the input. */
  label?: string;
  /** Initial value when uncontrolled (no `value`). Works with React Hook Form's `register`. */
  defaultValue?: string;
  /** Hint shown while the field is empty. Don't use it instead of a label; it disappears as soon as someone types. */
  placeholder?: string;
  /** Height and text size of the input. Default `medium`. */
  inputSize?: 'small' | 'medium' | 'large';
  /** Turns the control off: it can't be focused or changed, and it's announced as disabled. */
  disabled?: boolean;
  /** Shows the field in its error state. Pair it with `helperText` explaining what to fix. */
  error?: boolean;
  /** The current text, when you control the field yourself. Use `defaultValue` to let it manage its own state. */
  value?: string;
  /** Short guidance under the field. Shown in red with an error. */
  helperText?: string;
  /** Called on every keystroke with the change event; read `event.target.value`. */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /**
   * Called on every keystroke with the new text, then the event. Same shape as
   * `Textarea`, `Dropdown` and the other fields, so one handler style works everywhere.
   */
  onValueChange?: (value: string, event: React.ChangeEvent<HTMLInputElement>) => void;
  /** Called when the field gains focus. */
  onFocus?: (event: FocusEvent<HTMLInputElement>) => void;
  /** Called when the field loses focus. Handy for validating on blur. */
  onBlur?: (event: FocusEvent<HTMLInputElement>) => void;
  /**
   * Live Wire charge meter. A number from 0 to 1, or a function that maps the
   * current value to 0..1 (e.g. password strength). At 1 the field is fully
   * charged and current runs along the meter.
   */
  charge?: number | ((value: string) => number);
  /** Text announced next to the meter. Receives the charge as 0..100. */
  chargeLabel?: (percent: number) => React.ReactNode;
  /** Extra classes for each part: root, label, control, input, adornment, meter, helper. */
  classNames?: Partial<Record<'root' | 'label' | 'control' | 'input' | 'adornment' | 'meter' | 'helper', string>>;
  /** `outlined` (default) draws a full border, `filled` a tinted background, `standard` just an underline. */
  variant?: 'outlined' | 'filled' | 'standard';
  /** Content at the start of the input, like a currency symbol or a search icon. */
  prepend?: React.ReactNode;
  /** Content at the end of the input, like a unit (“kg”) or an icon button. */
  append?: React.ReactNode;
  /** Function that names the card network from the number typed, e.g. returns “Visa”; shown inside the field. */
  cardDetection?: (value: string) => string | undefined;
  /** Function that formats the value as it's typed, e.g. `98765 43210`. */
  formatPhoneNumber?: (value: string) => string;
  /** Inline styles for the wrapper around the label, input and helper text. */
  containerStyle?: React.CSSProperties;
  /** Formats the value as money while typing (thousand separators, two decimals). */
  isCurrency?: boolean;
  /** The kind of input, like `email`, `password` or `tel`. It sets the mobile keyboard and browser autofill. Default `text`. */
  type?:
  | "button"
  | "checkbox"
  | "color"
  | "date"
  | "datetime-local"
  | "email"
  | "file"
  | "hidden"
  | "image"
  | "month"
  | "password"
  | "radio"
  | "range"
  | "reset"
  | "search"
  | "submit"
  | "text"
  | "time"
  | "url"
  | "week"
  | 'card'
  | 'currency'
  | 'phone'
  | (string & {});
}

import React from 'react';

const TextFieldDropdown = ({ options }: { options: { label: string; value: string; }[] }) => (
  <select>
    {options.map((option) => (
      <option key={option.value} value={option.value}>{option.label}</option>
    ))}
  </select>
);

export default TextFieldDropdown;

import React from 'react';

export function useForkRef<T>(
  refA: React.Ref<T> | null | undefined, 
  refB: React.Ref<T> | null | undefined
): React.Ref<T> {
  return React.useMemo(() => {
    if (refA == null && refB == null) {
      return null;
    }
    return (refValue: T) => {
      if (typeof refA === 'function') {
        refA(refValue);
      } else if (refA) {
        (refA as React.MutableRefObject<T | null>).current = refValue;
      }

      if (typeof refB === 'function') {
        refB(refValue);
      } else if (refB) {
        (refB as React.MutableRefObject<T | null>).current = refValue;
      }
    };
  }, [refA, refB]);
}

import { ChangeEvent, FocusEvent, useState } from "react";
import { UseTextFieldProps, UseTextFieldResult } from "./Textfield.types";

// Enum for Input Types
enum InputType {
  CURRENCY = 'currency',
  CARD = 'card',
  PHONE = 'phone',
}

// Utility functions for masking input values
const useMasking = (type?: string) => {
  const maskCurrency = (value: string): string => {
    const numericValue = value.replace(/[^\d]/g, '');
    if (!numericValue) return '';

    const decimalPart = numericValue.slice(-2);
    const wholePart = numericValue.slice(0, -2);
    const formattedWholePart = wholePart.replace(/\B(?=(\d{3})+(?!\d))/g, ",");

    return decimalPart.length > 0
      ? `${formattedWholePart}${decimalPart.length > 0 ? '.' + decimalPart : ''}`
      : formattedWholePart;
  };

  const maskCreditCard = (value: string): string => {
    return value.replace(/\d(?=\d{4})/g, '*');
  };

  const formatPhoneNumber = (value: string): string => {
    const cleaned = value.replace(/\D/g, '');
    const match = cleaned.match(/^(\d{3})(\d{3})(\d{4})$/);
    return match ? `(${match[1]}) ${match[2]}-${match[3]}` : value;
  };

  return (value: string): string => {
    switch (type) {
      case InputType.CURRENCY:
        return maskCurrency(value);
      case InputType.CARD:
        return maskCreditCard(value);
      case InputType.PHONE:
        return formatPhoneNumber(value);
      default:
        return value;
    }
  };
};

export const useTextField = ({
  value: initialValue = '',
  onChange: onChangeProp,
  onFocus: onFocusProp,
  onBlur: onBlurProp,
  disabled = false,
  error = false,
  type,
}: UseTextFieldProps): UseTextFieldResult => {
  const [value, setValue] = useState(initialValue);
  const [focused, setFocused] = useState(false);

  const applyMasking = useMasking(type);

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const rawValue = event.target.value;
    const newValue = applyMasking(rawValue);
    // Write the masked value back so uncontrolled inputs (and form libraries
    // reading the DOM, like React Hook Form) see it too.
    if (newValue !== rawValue) event.target.value = newValue;
    setValue(newValue);
    onChangeProp?.(event);
  };

  const handleFocus = (event: FocusEvent<HTMLInputElement>) => {
    setFocused(true);
    if (onFocusProp) {
      onFocusProp(event);
    }
  };

  const handleBlur = (event: FocusEvent<HTMLInputElement>) => {
    setFocused(false);
    if (onBlurProp) {
      onBlurProp(event);
    }
  };

  return {
    value,
    onChange: handleChange,
    onFocus: handleFocus,
    onBlur: handleBlur,
    focused,
    disabled,
    error,
  };
};
